  Batch Add(string name,string color,int order,int landmark=-1,bool lower=false,bool overhead=false){var go=new GameObject("Stage54 "+name){hideFlags=HideFlags.DontSave};go.transform.SetParent(transform,false);var f=go.AddComponent<MeshFilter>();f.sharedMesh=new Mesh{name=go.name,hideFlags=HideFlags.DontSave};var rr=go.AddComponent<MeshRenderer>();rr.sharedMaterial=Live.materials[(int)PreviewLayer.Gobbo];rr.sortingOrder=order;rr.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;var b=new Batch{Data=new PreviewMeshData(go.name,PreviewLayer.Gobbo),Filter=f,Renderer=rr,Color=color,Landmark=landmark,Lower=lower,Overhead=overhead};batches.Add(b);return b;}
