  void BuildStructures(){long t=System.Diagnostics.Stopwatch.GetTimestamp();for(int l=0;l<State.Fixture.Landmarks.Count;l++){var land=State.Fixture.Landmarks[l];foreach(var part in land.Parts)for(int side=0;side<2;side++){
    if(l==0){var lower=Add(part.Id+" lower "+side,side==0?palette.Matter(State.Fixture.Materials[l]):"ExposedWallMoss",18,l,true);StructureMesh.Build(part,lower.Data,0,5,side==1);lower.Bounds=StructureMesh.Bounds(lower.Data);var upper=Add(part.Id+" exposed "+side,lower.Color,18,l);StructureMesh.Build(part,upper.Data,5,24,side==1);upper.Bounds=StructureMesh.Bounds(upper.Data);}
    else {var b=Add(part.Id+" "+side,side==0?palette.Matter(State.Fixture.Materials[l]):"PermanentMossBlack",part.Overhead?40:18,l,false,part.Overhead);StructureMesh.Build(part,b.Data,0,int.MaxValue,side==1);b.Bounds=StructureMesh.Bounds(b.Data);}
   }}foreach(var b in batches)if(b.Overhead){b.Original=b.Data;b.Data=new PreviewMeshData(b.Data.Name,PreviewLayer.Gobbo);StructureTerrainClip.Build(b.Original,b.Data,State.World,State.Fixture.Landmarks[b.Landmark]);}BuildProtected();veil=Add("reveal veil","FloorPlumShadow",32);veil.Bounds=new ProjectionBounds(new Point2(0,0),new Point2(Live.worldSize,Live.worldSize));clues=Add("terrain clues","LightDirtyAmber",30);clues.Bounds=new ProjectionBounds(new Point2(0,0),new Point2(Live.worldSize,Live.worldSize));AssemblyMs=StreamingGeometry.Elapsed(t);StructureBuilds++;}
  sealed class FootSource:IOccupancySource{readonly HashSet<int> cells=new HashSet<int>();public int Width{get;}public int Height=>Width;public FootSource(int w,IEnumerable<DualTile> footprint){Width=w;foreach(var c in footprint)cells.Add(c.Y*w+c.X);}public bool IsSolid(int x,int y)=>cells.Contains(y*Width+x);}
  void BuildProtected(){for(int l=0;l<State.Fixture.Landmarks.Count;l++){var land=State.Fixture.Landmarks[l];var source=new FootSource(Live.worldSize,land.Footprint);var cache=new ContourTerrainCache(source);var output=Add("protected "+l,palette.Matter(State.Fixture.Materials[l]),2,l,true);var seen=new HashSet<DualTile>();foreach(var c in land.Footprint){var key=StreamingCoordinates.Owner(c.X,c.Y);for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++)seen.Add(new DualTile(key.X+dx,key.Y+dy));}foreach(var key in seen){int x=key.X*16,y=key.Y*16;if(x<0||y<0||x>=Live.worldSize-1||y>=Live.worldSize-1)continue;for(int yy=y;yy<Math.Min(y+16,Live.worldSize-1);yy++)for(int xx=x;xx<Math.Min(x+16,Live.worldSize-1);xx++){int code=ContourGeometry.Classify(source.IsSolid(xx,yy),source.IsSolid(xx+1,yy),source.IsSolid(xx+1,yy+1),source.IsSolid(xx,yy+1));if(code==15){int start=xx;while(xx+1<Math.Min(x+16,Live.worldSize-1)&&source.IsSolid(xx+2,yy)&&source.IsSolid(xx+2,yy+1))xx++;output.Data.Rectangle(start+.5,yy+.5,xx+1.5,yy+1.5);}else if(code!=0)PreviewMeshBuilder.EmitCellSolid(source,xx,yy,output.Data);}}output.Bounds=StructureMesh.Bounds(output.Data);}}
  readonly HashSet<Batch> emergenceDirty=new HashSet<Batch>();
  void OnTerrainChange(TerrainCellChange c){foreach(var b in batches)if(b.Original!=null&&c.X>=b.Bounds.Min.X-2&&c.X<=b.Bounds.Max.X+2&&c.Y>=b.Bounds.Min.Y-2&&c.Y<=b.Bounds.Max.Y+2)emergenceDirty.Add(b);}
  public void SetReveal(int n){reveal=n;if(applied==n)return;applied=n;State.Presentation.Style=n>=2?BreakthroughStyle.Soft:n==1?BreakthroughStyle.Hybrid:BreakthroughStyle.Original;State.Discovery.ImmediateDistance=n==0||n==3?0:5;work.Clear();work.AddRange(frontier);Live.Stream.QueuePresentation(work);BuildVeil();}
  public void Process(double dt,bool explore=true){long t=System.Diagnostics.Stopwatch.GetTimestamp();EmergenceMs=0;if(emergenceDirty.Count>0){foreach(var b in emergenceDirty){StructureTerrainClip.Build(b.Original,b.Data,State.World,State.Fixture.Landmarks[b.Landmark]);b.Dirty=true;}emergenceDirty.Clear();EmergenceMs=StreamingGeometry.Elapsed(t);}var d=State.Discovery;d.ProcessChanges(Player);int x=(int)Player.X,y=(int)Player.Y;if(explore&&(x!=px||y!=py)){d.Explore(Player);px=x;py=y;}if(d.Tick(dt)>0){Live.Stream.QueuePresentation(d.Released);foreach(var cell in d.Released)for(int yy=cell.Y-1;yy<=cell.Y;yy++)for(int xx=cell.X-1;xx<=cell.X;xx++)frontier.Add(new DualTile(xx,yy));PruneFrontier();BuildVeil();}if(State.World.Revision!=lastRevision){lastRevision=State.World.Revision;PruneFrontier();BuildVeil();}UpdateClues();DiscoveryMs=StreamingGeometry.Elapsed(t);}
  void UpdateClues(){int mask=0;var list=State.Fixture.Clues;for(int i=0;i<list.Count;i++){var p=list[i].Position;if(LabNavigation.Distance(Player,p)>32)continue;bool visible=false;for(int y=(int)p.Y-3;y<=(int)p.Y+3;y++)for(int x=(int)p.X-3;x<=(int)p.X+3;x++)if(!State.World.IsSolid(x,y)&&State.Discovery.Shown(x,y))visible=true;if(visible)mask|=1<<i;}if(mask==clueMask||clues==null)return;clueMask=mask;clues.Data.Clear();for(int i=0;i<list.Count;i++)if((mask&(1<<i))!=0){var p=list[i].Position;Stage50Preview.Stroke(clues.Data,new Point2(p.X-.5,p.Y+.2),p,.045);Stage50Preview.Stroke(clues.Data,p,new Point2(p.X+.4,p.Y-.2),.045);}clues.Dirty=true;}
  void PruneFrontier(){work.Clear();foreach(var c in frontier){bool a=false,b=false,solid=false;for(int j=0;j<2;j++)for(int i=0;i<2;i++){solid|=State.World.IsSolid(c.X+i,c.Y+j);if(State.Discovery.Shown(c.X+i,c.Y+j))a=true;else b=true;}if(solid||!a||!b)work.Add(c);}foreach(var c in work)frontier.Remove(c);FrontierTiles=frontier.Count;}
  void BuildVeil(){if(veil==null)return;veil.Data.Clear();if(reveal>=2){var caches=new Dictionary<DualTile,ContourTerrainCache>();foreach(var c in frontier){var k=StreamingCoordinates.Owner(c.X,c.Y);if(!caches.TryGetValue(k,out var cache))caches[k]=cache=new ContourTerrainCache(new ChunkReadWindow(State.Presentation,k));foreach(var strip in cache.GetTile(c.X,c.Y))for(int j=0;j<strip.Samples.Count-1;j++)Stage50Preview.Stroke(veil.Data,strip.Samples[j].Logical,strip.Samples[j+1].Logical,.35);}}veil.Dirty=true;}
  public int Refill(){var cells=State.Fixture.Rubble;foreach(var c in cells)if(Math.Abs(Player.X-c.X-.5)<1&&Math.Abs(Player.Y-c.Y-.5)<1)return 0;return Live.Stream.Refill(cells);}
  void Update(){Initialize();Live.showUI=false;Lab.showPanel=false;Live.speed=testingSpeed;Live.settings.anchor=Anchors[Mathf.Clamp(anchor,0,1)];if(automation)return;var k=Keyboard.current;var m=Mouse.current;if(k!=null&&k.tabKey.wasPressedThisFrame)showPanel=!showPanel;Vector2 move=k==null?Vector2.zero:new Vector2((k.dKey.isPressed?1:0)-(k.aKey.isPressed?1:0),(k.sKey.isPressed?1:0)-(k.wKey.isPressed?1:0));bool over=showPanel&&m!=null&&m.position.ReadValue().x<345&&m.position.ReadValue().y>Screen.height-(advanced?760:280);var aim=Live.Aim;if(m!=null&&Live.Snapshot!=null&&!over){var q=Live.previewCamera.ScreenToWorldPoint(new Vector3(m.position.ReadValue().x,m.position.ReadValue().y,10));aim=V(Live.Snapshot.Unproject(new Point2(q.x,-q.y)))-Live.Position;}if(Live.Ready)Live.Step(move,aim,!over&&((m!=null&&m.leftButton.isPressed)||(k!=null&&k.spaceKey.isPressed)),Time.deltaTime);SetReveal(reveal);Process(Time.deltaTime);if(Lab.encounterCount>0)Lab.Advance(Math.Min(Time.deltaTime,.1));}
  void LateUpdate(){if(State==null||Live.Snapshot==null)return;long t=System.Diagnostics.Stopwatch.GetTimestamp();VisibleParts=StructureUploads=0;double w=CameraStudy.DisplayWidth,h=w/(16.0/9);var view=new ProjectionBounds(new Point2(-w*.5,-h*.5),new Point2(w*.5,h*.5));for(int l=0;l<groundShown.Length;l++)groundShown[l]=groundShown[l]||StructureMesh.GroundVisible(State.Fixture.Landmarks[l],State.Discovery);foreach(var b in batches){bool visible=Live.Ready&&b.Data.Indices.Count>0&&(!b.Lower||groundShown[b.Landmark])&&(b.Landmark<=0||groundShown[b.Landmark]);var bb=new ProjectionBounds(Live.Snapshot.Project(b.Bounds.Min),Live.Snapshot.Project(b.Bounds.Max));visible&=StructuralPrimitives.Intersects(bb,view);b.Renderer.enabled=visible;if(!visible)continue;float a=b==veil?.4f:1;if(b.Overhead&&cutaway){if(StructureMesh.Occludes(bb,Live.Snapshot,Player,Stage50Preview.VisualBounds(Player,1,0),0))a=.22f;for(int i=0;i<Lab.encounterCount;i++)if(Lab.PresentationAllowed(Lab.Actors[i].Position)&&StructureMesh.Occludes(bb,Live.Snapshot,Lab.Actors[i].Position,Stage50Preview.VisualBounds(Lab.Actors[i].Position,Lab.Actors[i].Size,Lab.Actors[i].Kind),0))a=.22f;}var color=palette.Color(b.Color);color.a=a;b.Renderer.GetPropertyBlock(block);block.SetColor("_Color",color);b.Renderer.SetPropertyBlock(block);if(Live.Gpu.Draw(b.Data,b.Filter,b.Bounds,b.Dirty))StructureUploads++;b.Dirty=false;VisibleParts++;}StructureMs=StreamingGeometry.Elapsed(t);}
  void OnGUI(){if(!showPanel||State==null)return;if(debug){int row=0;foreach(var e in palette.entries){var previous=GUI.color;GUI.color=palette.Color(e.name);GUI.DrawTexture(new Rect(Screen.width-270,8+row*26,258,24),Texture2D.whiteTexture);GUI.color=UnityEngine.Color.white;GUI.Label(new Rect(Screen.width-268,8+row*26,255,24),e.name+" "+e.hex);GUI.color=previous;row++;}}GUILayout.BeginArea(new Rect(8,8,335,advanced?750:270),GUI.skin.box);scroll=GUILayout.BeginScrollView(scroll);GUILayout.Label("SPORE GOBBO · CAVE EXPLORATION 5.4");GUILayout.Label("WASD · mouse aim · LMB / Space dig · Tab UI");GUILayout.Label("Explore the north rim; dig to find side pockets.");GUILayout.Label("Camera");anchor=GUILayout.Toolbar(anchor,new[]{"Current 62%","Alternative 57%"});GUILayout.Label("Location");int n=GUILayout.Toolbar(location,new[]{"Start","Spike","Roots","Hidden Network"});if(n!=location)Go(n);GUILayout.Label("Reveal");reveal=GUILayout.Toolbar(reveal,new[]{"Original","Hybrid","Refined"});GUILayout.BeginHorizontal();debug=GUILayout.Toggle(debug,"Debug");advanced=GUILayout.Toggle(advanced,"Diagnostics");if(GUILayout.Button("Reset Test"))ResetDemo();GUILayout.EndHorizontal();if(debug)GUILayout.Label("Diggable: Umber · Protected: Grey stone / Limestone bone / Sepia roots");if(advanced){GUILayout.Label("Speed "+testingSpeed.ToString("F0"));testingSpeed=GUILayout.HorizontalSlider(testingSpeed,1,30);GUILayout.Label("Spike height (reset) "+spikeHeight);spikeHeight=GUILayout.HorizontalSlider(spikeHeight,16,42);GUILayout.Label("Spike width (reset) "+spikeWidth);spikeWidth=GUILayout.HorizontalSlider(spikeWidth,4,10);cutaway=GUILayout.Toggle(cutaway,"Structure cutaway");Live.showGrid=GUILayout.Toggle(Live.showGrid,"Logical grid");if(GUILayout.Button("Soft reference"))SetReveal(3);if(GUILayout.Button("Refill designated rubble"))Refill();GUILayout.Label("Palette samples (presentation only; tiers2/3 add no resistance)");foreach(var e in palette.entries){var old=GUI.color;GUI.color=palette.Color(e.name);GUILayout.Box(e.name+" "+e.hex);GUI.color=old;}GUILayout.Label(CameraStudy.Diagnostics());GUILayout.Label($"Discovery {DiscoveryMs:F3}ms · publication {Live.Stream.PresentationMs:F3}ms\nStructure draw {StructureMs:F3}ms · assembly {AssemblyMs:F3}ms\nRemembered {State.Discovery.Remembered.Count} · resident {Live.Stream.Resident.Count}/384\n{status}");}GUILayout.EndScrollView();GUILayout.EndArea();}
  public string Inspect(){var s=new System.Text.StringBuilder();for(int l=0;l<3;l++){s.AppendLine(State.Fixture.Landmarks[l].Id+" cached="+groundShown[l]+" calculated="+StructureMesh.GroundVisible(State.Fixture.Landmarks[l],State.Discovery));foreach(var c in State.Fixture.Landmarks[l].Contacts)for(int y=c.Y-7;y<=c.Y+7;y++)for(int x=c.X-7;x<=c.X+7;x++)if(!State.World.IsSolid(x,y)&&State.Discovery.Shown(x,y)){s.AppendLine("known floor "+x+","+y+" indexed="+State.Index.ByCell.ContainsKey(y*State.World.Width+x)+" visual="+State.Discovery.Visual.Contains(y*State.World.Width+x));goto next;}next:;}foreach(var b in batches)s.AppendLine(b.Data.Name+" landmark="+b.Landmark+" rendered="+b.Renderer.enabled);return s.ToString();}
